/**
 * Sentinel theme — void field, square geometry, violet primary, ice/indigo
 * registers. Visual identity only; no Sentinel-specific component forks.
 *
 * Registers (set via data-register on GameScienceProvider / documentElement):
 *   cinematic  — default; ice secondary, panel wash, cooler void
 *   restrained — indigo secondary, quieter borders, no wash
 *
 * Font stacks reference Archivo, Instrument Sans, and IBM Plex Mono with
 * system fallbacks. Font files are application-owned — load via HTML <link> or
 * approved packages (see docs/font-loading.md). This file must not contain
 * remote @import statements (Tailwind 4 / Lightning CSS consumers break on them).
 * Builds and smoke tests must not require a remote font provider.
 */

[data-theme="sentinel"] {
  /* Page and surfaces — cinematic void #02050A, ink #EAF6FF */
  --background: 0.113 0.017 250.8;
  --foreground: 0.967 0.018 240;

  --surface-subtle: 0.143 0.025 255.7;
  --surface: 0.148 0.023 255.1;
  --surface-raised: 0.178 0.034 259.9;
  --surface-overlay: 0.142 0.018 271.7;

  /* Borders — ice composited onto void (16% / 34%) */
  --border: 0.26 0.03 239.5;
  --border-strong: 0.4 0.047 233.6;
  --focus-ring: 0.836 0.102 230;

  /* Primary — violet #B983FF; CTA ink is void */
  --primary: 0.715 0.18 302.2;
  --primary-hover: 0.747 0.159 302.8;
  --primary-active: 0.64 0.159 302.2;
  --primary-foreground: 0.113 0.017 250.8;

  /* Secondary — cinematic ice #7FD6FF */
  --secondary: 0.836 0.102 230;
  --secondary-hover: 0.851 0.093 229.5;
  --secondary-active: 0.76 0.092 230;
  --secondary-foreground: 0.113 0.017 250.8;

  /* Accent — mint #5EE39A */
  --accent: 0.823 0.157 156.3;
  --accent-foreground: 0.113 0.017 250.8;

  /* Muted — void-adjacent surface / #98A0B2 */
  --muted: 0.143 0.025 255.7;
  --muted-foreground: 0.705 0.028 266.5;

  /* Status — success maps to mint; information to ice; danger is overrun only */
  --success: 0.823 0.157 156.3;
  --success-foreground: 0.113 0.017 250.8;

  --warning: 0.676 0.115 75.1;
  --warning-foreground: 0.113 0.017 250.8;

  --danger: 0.688 0.201 24.1;
  --danger-foreground: 0.967 0.018 240;

  --information: 0.836 0.102 230;
  --information-foreground: 0.113 0.017 250.8;

  /* Shape — square controls/surfaces; pill is the only radius */
  --radius-control: 0;
  --radius-card: 0;
  --radius-panel: 0;
  --radius-overlay: 0;
  --radius-pill: 1.75rem;

  --border-width-control: 1px;
  --border-width-panel: 1px;

  /* Typography — Archivo display, Instrument Sans body, IBM Plex Mono data */
  --font-display: Archivo, system-ui, sans-serif;
  --font-body: "Instrument Sans", system-ui, -apple-system, sans-serif;
  --font-mono: "IBM Plex Mono", ui-monospace, monospace;
  --font-data: var(--font-mono);

  --font-weight-heading: 600;
  --font-weight-label: 500;
  --font-weight-body: 400;

  --tracking-heading: 0;
  --tracking-label: 0.28em;
  --text-transform-label: uppercase;

  /* Controls — 44px default touch target */
  --control-height-sm: 2.5rem;
  --control-height-md: 2.75rem;
  --control-height-lg: 3.25rem;

  --control-padding-inline-sm: 0.75rem;
  --control-padding-inline-md: 1rem;
  --control-padding-inline-lg: 1.25rem;

  /* Panels and spacing */
  --panel-padding-sm: 1rem;
  --panel-padding-md: 1.25rem;
  --panel-padding-lg: 1.75rem;

  --section-gap: 1.25rem;
  --content-max-width: 24rem;

  /* Depth — no control/card shadow; focus is a visible ice ring */
  --shadow-control: none;
  --shadow-card: none;
  --shadow-overlay: 0 24px 64px rgb(0 0 0 / 0.55);
  --shadow-focus: 0 0 0 2px oklch(var(--background)), 0 0 0 4px oklch(var(--focus-ring) / 0.8);

  /* Motion — 180 / 360 / 800ms ease-out; ambient loops 2–6s */
  --duration-fast: 180ms;
  --duration-standard: 360ms;
  --duration-emphasis: 800ms;
  --duration-ambient: 4s;

  --ease-standard: cubic-bezier(0.22, 1, 0.36, 1);
  --ease-emphasis: cubic-bezier(0.22, 1, 0.36, 1);

  --press-scale: 0.98;
  --hover-translate: 0px;

  /* Shell — void field, no globe / rain / radar */
  --gs-shell-gradient: linear-gradient(180deg, oklch(0.113 0.017 250.8), oklch(0.113 0.017 250.8));

  --shell-vignette: radial-gradient(
    ellipse at center,
    transparent 0%,
    transparent 55%,
    oklch(0.113 0.017 250.8 / 0.35) 88%,
    oklch(0.113 0.017 250.8 / 0.7) 100%
  );

  --panel-surface-alpha: 1;
  --panel-border-alpha: 1;
  --overlay-scrim-alpha: 0.55;
  --overlay-border-alpha: 0.45;
  --input-surface: var(--surface-raised);
  --side-panel-width: 26.25rem;

  /* Heat map — indigo → amber for progress fill */
  --heat-0: 0.667 0.166 276.7;
  --heat-1: 0.66 0.114 288.1;
  --heat-2: 0.652 0.048 326.1;
  --heat-3: 0.661 0.065 61.5;
  --heat-4: 0.676 0.115 75.1;

  --tracking-data: 0.14em;

  --action-bar-pad-top: 1.5rem;
  --action-bar-safe-bottom: max(1.25rem, env(safe-area-inset-bottom));
  --action-bar-bleed: linear-gradient(
    to top,
    oklch(0.113 0.017 250.8 / 0.96),
    oklch(0.113 0.017 250.8 / 0.55) 70%,
    transparent
  );

  --glow-critical: none;
}

/* Restrained register — quieter void, indigo secondary, no ice wash */
[data-theme="sentinel"][data-register="restrained"] {
  --background: 0.14 0.017 263.5;
  --foreground: 0.957 0.009 258.3;

  --surface-subtle: 0.171 0.026 269.4;
  --surface: 0.178 0.024 265.2;
  --surface-raised: 0.25 0.036 267.5;
  --surface-overlay: 0.142 0.018 271.7;

  --border: 0.235 0.014 267;
  --border-strong: 0.309 0.013 267.1;
  --focus-ring: 0.667 0.166 276.7;

  --secondary: 0.667 0.166 276.7;
  --secondary-hover: 0.7 0.148 277.6;
  --secondary-active: 0.608 0.15 276.8;
  --secondary-foreground: 0.14 0.017 263.5;

  --muted: 0.171 0.026 269.4;
  --muted-foreground: 0.5 0.032 267.2;

  --information: 0.667 0.166 276.7;
  --information-foreground: 0.14 0.017 263.5;

  --gs-shell-gradient: linear-gradient(180deg, oklch(0.14 0.017 263.5), oklch(0.14 0.017 263.5));

  --shell-vignette: radial-gradient(
    ellipse at center,
    transparent 0%,
    transparent 58%,
    oklch(0.14 0.017 263.5 / 0.28) 88%,
    oklch(0.14 0.017 263.5 / 0.55) 100%
  );

  --action-bar-bleed: linear-gradient(
    to top,
    oklch(0.14 0.017 263.5 / 0.96),
    oklch(0.14 0.017 263.5 / 0.55) 70%,
    transparent
  );
}

/* Shared-display density must not soften Sentinel geometry */
[data-theme="sentinel"][data-context="shared-display"] {
  --radius-panel: 0;
  --radius-control: 0;
  --radius-card: 0;
  --radius-overlay: 0;
  --content-max-width: 100%;
}

[data-theme="sentinel"][data-context="participant"] {
  --content-max-width: 24rem;
  --control-height-md: 2.75rem;
  --control-height-lg: 3.25rem;
}

[data-theme="sentinel"][data-context="facilitator"] {
  --content-max-width: 48rem;
  --control-height-sm: 2rem;
  --control-height-md: 2.25rem;
  --control-height-lg: 2.75rem;
  --type-scale-label: 0.75rem;
}

/* -------------------------------------------------------------------------- */
/* Button — square, panel surface, strong border, no shadow, 44px min-height  */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-button {
  border-radius: var(--radius-control);
  box-shadow: none;
  min-height: 2.75rem;
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: var(--text-transform-label);
}

[data-theme="sentinel"] .gs-button[data-intent="primary"],
[data-theme="sentinel"] .gs-button[data-intent="outline"],
[data-theme="sentinel"] .gs-button[data-emphasis="strong"] {
  border-color: oklch(var(--border-strong));
}

[data-theme="sentinel"] .gs-button[data-intent="outline"],
[data-theme="sentinel"] .gs-button[data-intent="ghost"] {
  background: oklch(var(--surface));
}

[data-theme="sentinel"] .gs-button[data-intent="secondary"] {
  border-color: oklch(var(--secondary) / 0.45);
}

[data-theme="sentinel"] .gs-button:disabled,
[data-theme="sentinel"] .gs-button[aria-disabled="true"],
[data-theme="sentinel"] .gs-button[data-disabled] {
  opacity: 0.55;
  color: oklch(var(--muted-foreground));
  border-color: oklch(var(--border));
  box-shadow: none;
}

[data-theme="sentinel"] .gs-button:focus-visible {
  box-shadow: var(--shadow-focus);
}

[data-theme="sentinel"][data-context="facilitator"] .gs-button {
  min-height: var(--control-height-md);
}

@media (prefers-reduced-motion: reduce) {
  [data-theme="sentinel"] .gs-button {
    --press-scale: 1;
  }
}

/* -------------------------------------------------------------------------- */
/* Input / Textarea / Label                                                    */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-input {
  background: oklch(var(--surface-raised));
  border-color: oklch(var(--border-strong));
  border-radius: var(--radius-control);
  box-shadow: none;
  color: oklch(var(--foreground));
  font-family: var(--font-body);
}

[data-theme="sentinel"] .gs-input:hover:not(:disabled):not([aria-invalid="true"]) {
  border-color: oklch(var(--focus-ring) / 0.7);
}

[data-theme="sentinel"] .gs-input:focus-visible {
  border-color: oklch(var(--focus-ring));
  box-shadow: var(--shadow-focus);
  outline: none;
}

[data-theme="sentinel"] .gs-input::placeholder {
  color: oklch(var(--muted-foreground));
}

[data-theme="sentinel"] .gs-input[aria-invalid="true"] {
  border-color: oklch(var(--danger));
}

[data-theme="sentinel"] .gs-input:disabled {
  opacity: 0.55;
  color: oklch(var(--muted-foreground));
}

[data-theme="sentinel"] .gs-label {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: var(--text-transform-label);
}

[data-theme="sentinel"] .gs-eyebrow {
  color: oklch(var(--secondary));
  font-family: var(--font-mono);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
}

/* -------------------------------------------------------------------------- */
/* Forms — checkbox, radio, switch, select, slider, tabs, accordion           */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-checkbox,
[data-theme="sentinel"] .gs-radio {
  border-color: oklch(var(--border-strong));
  background: oklch(var(--surface-raised));
  border-radius: var(--radius-control);
}

[data-theme="sentinel"] .gs-radio {
  border-radius: 9999px;
}

[data-theme="sentinel"] .gs-checkbox[data-state="checked"],
[data-theme="sentinel"] .gs-radio[data-state="checked"] {
  border-color: oklch(var(--primary));
  background: oklch(var(--primary));
  color: oklch(var(--primary-foreground));
}

[data-theme="sentinel"] .gs-switch {
  border-radius: var(--radius-control);
  background: oklch(var(--muted));
  border: 1px solid oklch(var(--border-strong));
}

[data-theme="sentinel"] .gs-switch[data-state="checked"] {
  background: oklch(var(--primary));
  border-color: oklch(var(--primary));
}

[data-theme="sentinel"] .gs-select-trigger {
  background: oklch(var(--surface-raised));
  border-color: oklch(var(--border-strong));
  border-radius: var(--radius-control);
  color: oklch(var(--foreground));
  box-shadow: none;
}

[data-theme="sentinel"] .gs-select-trigger:focus,
[data-theme="sentinel"] .gs-select-trigger:focus-visible {
  border-color: oklch(var(--focus-ring));
  box-shadow: var(--shadow-focus);
  outline: none;
}

[data-theme="sentinel"] .gs-select-content,
[data-theme="sentinel"] .gs-popover-content,
[data-theme="sentinel"] .gs-dropdown-content {
  background: oklch(var(--surface-raised));
  border-color: oklch(var(--border-strong));
  border-radius: var(--radius-control);
  box-shadow: var(--shadow-overlay);
}

[data-theme="sentinel"] .gs-slider-track {
  border-radius: 0;
  background: oklch(var(--muted));
}

[data-theme="sentinel"] .gs-slider-range {
  background: linear-gradient(
    90deg,
    oklch(var(--heat-0)),
    oklch(var(--heat-2)),
    oklch(var(--heat-4))
  );
}

[data-theme="sentinel"] .gs-slider-thumb {
  border-radius: 0;
  border-color: oklch(var(--primary));
  background: oklch(var(--background));
}

[data-theme="sentinel"] .gs-tabs-list {
  border-radius: var(--radius-control);
  background: oklch(var(--surface));
  border: 1px solid oklch(var(--border));
}

[data-theme="sentinel"] .gs-tabs-trigger {
  border-radius: var(--radius-control);
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
}

[data-theme="sentinel"] .gs-tabs-trigger[data-state="active"] {
  background: oklch(var(--primary) / 0.12);
  color: oklch(var(--primary));
  box-shadow: inset 0 -2px 0 oklch(var(--primary));
}

[data-theme="sentinel"] .gs-accordion-item {
  border-color: oklch(var(--border));
}

[data-theme="sentinel"] .gs-accordion-trigger {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: 0.12em;
  text-transform: uppercase;
}

/* -------------------------------------------------------------------------- */
/* Panel / Card / Separator / Empty / Table                                   */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-panel {
  position: relative;
  background: oklch(var(--surface));
  border: var(--border-width-panel) solid oklch(var(--border-strong));
  border-radius: var(--radius-panel);
  box-shadow: none;
}

[data-theme="sentinel"] .gs-panel[data-elevation="subtle"] {
  background: oklch(var(--surface-subtle));
}

[data-theme="sentinel"] .gs-panel[data-elevation="raised"] {
  background: oklch(var(--surface-raised));
}

[data-theme="sentinel"] .gs-panel[data-elevation="overlay"] {
  background: oklch(var(--surface-overlay) / var(--overlay-scrim-alpha));
  border: 1px dashed oklch(var(--border-strong) / var(--overlay-border-alpha));
  box-shadow: var(--shadow-overlay);
}

[data-theme="sentinel"] .gs-panel[data-emphasis="strong"] {
  border-color: oklch(var(--border-strong));
}

[data-theme="sentinel"] .gs-panel > .gs-panel-content {
  position: relative;
  z-index: 0;
  min-width: 0;
}

/* Cinematic wash — opt-in class; paints only when register is not restrained */
[data-theme="sentinel"]:not([data-register="restrained"]) .gs-panel-wash::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background:
    radial-gradient(ellipse at 0% 0%, oklch(var(--secondary) / 0.1), transparent 52%),
    linear-gradient(180deg, oklch(var(--foreground) / 0.03), transparent 40%);
}

[data-theme="sentinel"][data-register="restrained"] .gs-panel-wash::after {
  content: none;
}

[data-theme="sentinel"] .gs-card {
  position: relative;
  background: oklch(var(--surface));
  border: 1px solid oklch(var(--border-strong));
  border-radius: var(--radius-card);
  box-shadow: none;
}

[data-theme="sentinel"] .gs-card[data-state="breached"] {
  background: oklch(var(--surface-subtle));
  border-color: oklch(var(--muted-foreground) / 0.35);
  color: oklch(var(--muted-foreground));
}

[data-theme="sentinel"] .gs-separator {
  background: oklch(var(--border));
}

[data-theme="sentinel"] .gs-separator[data-treatment="hairline"] {
  background: oklch(var(--border));
}

[data-theme="sentinel"] .gs-eyebrow-dotted {
  color: oklch(var(--secondary));
  font-family: var(--font-mono);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
}

[data-theme="sentinel"] .gs-countdown[data-intent="critical"],
[data-theme="sentinel"] .gs-countdown[data-state="expired"] {
  color: oklch(var(--danger));
}

[data-theme="sentinel"]
  .gs-phase-directive[data-treatment="panel"][data-intent="critical"]
  .gs-panel,
[data-theme="sentinel"] .gs-outcome-summary[data-intent="critical"] .gs-panel {
  border-color: oklch(var(--danger) / 0.55);
}

[data-theme="sentinel"]
  .gs-phase-directive[data-treatment="panel"][data-intent="warning"]
  .gs-panel,
[data-theme="sentinel"] .gs-outcome-summary[data-intent="warning"] .gs-panel {
  border-color: oklch(var(--warning) / 0.55);
}

[data-theme="sentinel"]
  .gs-phase-directive[data-treatment="panel"][data-intent="information"]
  .gs-panel,
[data-theme="sentinel"] .gs-outcome-summary[data-intent="information"] .gs-panel {
  border-color: oklch(var(--information) / 0.45);
}

[data-theme="sentinel"] .gs-outcome-summary[data-intent="success"] .gs-panel {
  border-color: oklch(var(--success) / 0.45);
}

[data-theme="sentinel"] .gs-sticky-action-bar {
  background-image: var(--action-bar-bleed);
}

[data-theme="sentinel"] .gs-empty {
  border-color: oklch(var(--border));
  border-radius: var(--radius-panel);
  background: oklch(var(--surface-subtle));
}

[data-theme="sentinel"] .gs-table {
  border-collapse: collapse;
}

[data-theme="sentinel"] .gs-table th {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  color: oklch(var(--muted-foreground));
  border-bottom-color: oklch(var(--border));
}

[data-theme="sentinel"] .gs-table td {
  border-bottom-color: oklch(var(--border));
}

/* -------------------------------------------------------------------------- */
/* Badge / Alert                                                               */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-badge {
  font-family: var(--font-mono);
  font-weight: var(--font-weight-label);
  letter-spacing: var(--tracking-label);
  text-transform: uppercase;
  border-radius: var(--radius-pill);
  padding-inline: 0.6rem;
  padding-block: 0.125rem;
}

[data-theme="sentinel"] .gs-badge[data-treatment="outlined"] {
  background: transparent;
}

[data-theme="sentinel"] .gs-alert {
  background: oklch(var(--surface));
  border-radius: var(--radius-panel);
  border-width: 1px;
  border-color: oklch(var(--border-strong));
}

[data-theme="sentinel"] .gs-alert[data-intent="information"] {
  border-color: oklch(var(--information));
}

[data-theme="sentinel"] .gs-alert[data-intent="success"] {
  border-color: oklch(var(--success));
}

[data-theme="sentinel"] .gs-alert[data-intent="warning"] {
  border-color: oklch(var(--warning));
}

[data-theme="sentinel"] .gs-alert[data-intent="danger"] {
  border-color: oklch(var(--danger));
}

/* -------------------------------------------------------------------------- */
/* Overlays — dialog / sheet / tooltip / toaster                              */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-dialog-overlay,
[data-theme="sentinel"] .gs-overlay {
  background: oklch(var(--surface-overlay) / var(--overlay-scrim-alpha));
}

[data-theme="sentinel"] .gs-dialog-content,
[data-theme="sentinel"] .gs-sheet-content {
  background: oklch(var(--surface-raised));
  border: 1px dashed oklch(var(--border-strong) / var(--overlay-border-alpha));
  border-radius: var(--radius-overlay);
  box-shadow: var(--shadow-overlay);
  font-family: var(--font-body);
}

[data-theme="sentinel"] .gs-tooltip-content {
  background: oklch(var(--surface-raised));
  color: oklch(var(--foreground));
  border: 1px solid oklch(var(--border-strong));
  border-radius: var(--radius-control);
  font-family: var(--font-mono);
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

[data-theme="sentinel"] .gs-toaster [data-sonner-toast],
[data-theme="sentinel"] .gs-toaster .toast {
  background: oklch(var(--surface-raised)) !important;
  color: oklch(var(--foreground)) !important;
  border-color: oklch(var(--border-strong)) !important;
  border-radius: var(--radius-control) !important;
  box-shadow: none !important;
}

/* -------------------------------------------------------------------------- */
/* Progress / Skeleton / Spinner                                              */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-progress {
  background: oklch(var(--surface-subtle));
  border: 1px solid oklch(var(--border));
  border-radius: 0;
  overflow: hidden;
}

[data-theme="sentinel"] .gs-progress-indicator {
  background: linear-gradient(
    90deg,
    oklch(var(--heat-0)),
    oklch(var(--heat-2)),
    oklch(var(--heat-4))
  );
}

[data-theme="sentinel"] .gs-skeleton {
  background: oklch(var(--surface-raised));
  border-radius: var(--radius-control);
  background-image: linear-gradient(
    90deg,
    oklch(var(--surface-raised)),
    oklch(var(--border) / 0.55),
    oklch(var(--surface-raised))
  );
  background-size: 200% 100%;
  animation: gs-sentinel-skeleton var(--duration-ambient) linear infinite;
}

@keyframes gs-sentinel-skeleton {
  0% {
    background-position: 100% 0;
  }
  100% {
    background-position: -100% 0;
  }
}

@media (prefers-reduced-motion: reduce) {
  [data-theme="sentinel"] {
    --duration-ambient: 0ms;
  }

  [data-theme="sentinel"] .gs-skeleton {
    animation: none;
    background-image: none;
  }
}

[data-theme="sentinel"] .gs-spinner {
  color: oklch(var(--secondary));
}

/* -------------------------------------------------------------------------- */
/* Display / mono / connection                                                */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-display,
[data-theme="sentinel"] .gs-display-hero {
  font-family: var(--font-display);
  font-weight: var(--font-weight-heading);
  letter-spacing: var(--tracking-heading);
  line-height: 1.05;
}

[data-theme="sentinel"] .gs-title-page {
  font-family: var(--font-display);
  font-weight: 500;
  letter-spacing: var(--tracking-heading);
}

[data-theme="sentinel"] .gs-title-section {
  font-family: var(--font-display);
  font-weight: 600;
  letter-spacing: 0.02em;
}

[data-theme="sentinel"] .gs-mono,
[data-theme="sentinel"] .gs-data {
  font-family: var(--font-mono);
  font-weight: 500;
  letter-spacing: var(--tracking-data);
  font-variant-numeric: tabular-nums;
}

[data-theme="sentinel"] .gs-connection-marker {
  width: 0.5rem;
  height: 0.5rem;
  border-radius: 9999px;
}

/* -------------------------------------------------------------------------- */
/* Shells — void field + vignette; no globe / rain / radar                    */
/* -------------------------------------------------------------------------- */

[data-theme="sentinel"] .gs-shell {
  position: relative;
  isolation: isolate;
}

[data-theme="sentinel"] .gs-shell::after {
  content: "";
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  background-image: var(--shell-vignette);
}

[data-theme="sentinel"] .gs-shell > * {
  position: relative;
  z-index: 1;
}

[data-theme="sentinel"] .gs-shell-footer {
  position: sticky;
  bottom: 0;
  z-index: 2;
  margin-top: auto;
  padding-top: var(--action-bar-pad-top);
  background-image: var(--action-bar-bleed);
}

[data-theme="sentinel"][data-context="shared-display"] .gs-display,
[data-theme="sentinel"][data-context="shared-display"] .gs-display-hero {
  font-size: var(--type-scale-display);
}
